<script setup>import {ref,computed} from 'vue';import AppShell from '../../components/AppShell.vue';import StatusPill from '../../components/StatusPill.vue';import {workOrders} from '../../api/mock';const tab=ref('全部'),keyword=ref('');const rows=computed(()=>workOrders.filter(w=>(tab.value==='全部'||w.status===tab.value)&&(w.no.includes(keyword.value)||w.product.includes(keyword.value))))</script>
<template><AppShell mode="admin"><div class="page-head"><div><span class="breadcrumb">生产管理 / 生产工单</span><h1>生产工单</h1><p>统一查看工单下达、执行、暂停与完工状态。</p></div><div class="head-actions"><button class="secondary">导入计划</button><button class="primary">+ 新建工单</button></div></div><section class="panel list-panel"><div class="summary-strip"><div><span>今日工单</span><b>5</b></div><div><span>计划数量</span><b>5,160</b></div><div><span>已完成</span><b>3,472</b></div><div><span>延期风险</span><b class="danger-text">1</b></div></div><div class="toolbar"><div class="tabs"><button v-for="t in ['全部','已下达','生产中','暂停','已完工']" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}<em>{{t==='全部'?5:t==='生产中'?2:1}}</em></button></div><div class="filters"><input v-model="keyword" placeholder="搜索工单号或产品"/><select><option>全部车间</option><option>装配车间</option><option>机加车间</option></select><button class="secondary">筛选</button></div></div><table class="workorder-table"><thead><tr><th>优先级</th><th>生产工单</th><th>产品</th><th>工作中心</th><th>计划数量</th><th>完工 / 不良</th><th>执行进度</th><th>交期</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="w in rows" :key="w.no"><td><span class="priority" :class="w.priority">{{w.priority}}</span></td><td><b>{{w.no}}</b><small>{{w.batch}}</small></td><td><b>{{w.product}}</b><small>{{w.code}}</small></td><td>{{w.center}}<small>{{w.workshop}}</small></td><td>{{w.plan.toLocaleString()}}</td><td>{{w.done.toLocaleString()}} <small>不良 {{w.defect}}</small></td><td><span class="progress wide-progress"><i :style="{width:w.progress+'%'}"></i></span><b>{{w.progress}}%</b></td><td>{{w.due}}</td><td><StatusPill :text="w.status"/></td><td><button class="more">•••</button></td></tr></tbody></table><div class="pagination"><span>共 5 条工单</span><div><button>‹</button><button class="active">1</button><button>›</button></div></div></section></AppShell></template>
